//! Zero-allocation, no_std command parser shared with other Xila executables.
//! Errors and help text are generated by getargs-derive at compile time.
use alloc::string::String;
use getargs_derive::{GetArgs, Subcommand};

/// Install an application package from Xila's virtual filesystem.
#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
pub struct Install<'a> {
    /// Path to a .xpk archive in the Xila virtual filesystem.
    pub archive: &'a str,

    /// Verify this installation with the supplied raw Ed25519 public key.
    #[arg(long = "public-key", conflicts_with = "allow_untrusted")]
    pub public_key: Option<&'a str>,

    /// Accept an untrusted or unsigned publisher, while still checking hashes.
    #[arg(long = "allow-untrusted", conflicts_with = "public_key")]
    pub allow_untrusted: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Subcommand)]
pub enum Command<'a> {
    /// Verify and install an application archive.
    Install(Install<'a>),
    /// List installed application bundles.
    List,
}

/// Native CLI for installing signed Xila application packages.
#[derive(Debug, Clone, PartialEq, Eq, GetArgs)]
#[command(name = "package", version)]
struct Cli<'a> {
    #[command(subcommand)]
    command: Command<'a>,
}

pub fn parse<'a>(args: &'a [String]) -> Result<Command<'a>, getargs_derive::Error<'a>> {
    Cli::from_args(args.iter().map(String::as_str)).map(|cli| cli.command)
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::{string::ToString, vec, vec::Vec};

    fn args(parts: &[&str]) -> Vec<String> {
        parts.iter().map(|part| (*part).to_string()).collect()
    }

    #[test]
    fn default_install_requires_a_trusted_signer() {
        let input = args(&["install", "/temporary/example.xpk"]);
        assert_eq!(
            parse(&input),
            Ok(Command::Install(Install {
                archive: "/temporary/example.xpk",
                public_key: None,
                allow_untrusted: false,
            }))
        );
    }

    #[test]
    fn unfamiliar_publisher_requires_an_explicit_override_or_key() {
        let untrusted = args(&["install", "/temporary/example.xpk", "--allow-untrusted"]);
        assert_eq!(
            parse(&untrusted),
            Ok(Command::Install(Install {
                archive: "/temporary/example.xpk",
                public_key: None,
                allow_untrusted: true,
            }))
        );
        let custom_key = args(&["install", "x.xpk", "--public-key", "/keys/user.pub"]);
        assert_eq!(
            parse(&custom_key),
            Ok(Command::Install(Install {
                archive: "x.xpk",
                public_key: Some("/keys/user.pub"),
                allow_untrusted: false,
            }))
        );
        let conflict = args(&[
            "install",
            "x.xpk",
            "--allow-untrusted",
            "--public-key",
            "/keys/test.pub",
        ]);
        assert!(parse(&conflict).is_err());
    }

    #[test]
    fn reject_invalid_arguments_and_generate_help() {
        for parts in [
            vec!["install", "x.xpk", "--public-key"],
            vec!["install", "x.xpk", "--unknown"],
            vec!["install"],
            vec!["unknown"],
        ] {
            let input = args(&parts);
            assert!(parse(&input).is_err(), "{parts:?}");
        }
        let list = args(&["list"]);
        assert_eq!(parse(&list), Ok(Command::List));
        for parts in [vec!["--help"], vec!["install", "--help"], vec!["--version"]] {
            let input = args(&parts);
            let error = parse(&input).unwrap_err();
            assert!(error.is_help() || error.is_version());
        }
        assert!(Cli::HELP.contains("Usage: package"));
        assert!(Cli::HELP.contains("install"));
    }
}
